def unique_plan(definition: FormalMethodDefinition) -> tuple[MethodStep, ...]:
    """Stable topological order; textual descriptions do not act as conditions.

    This local lower bound includes the root and its direct invocations.
    ``expand_unique_plan`` additionally enforces each whole subtree's limits.
    """
    procedure = definition.procedure
    if not isinstance(procedure, Orchestration):
        raise ValueError("A unique plan requires an orchestration definition")
    if procedure.has_candidate_choice:
        raise ValueError("Runner lacks conditional candidate selection")
    if procedure.object_batch:
        raise ValueError("Runner lacks bounded object fanout")
    if procedure.max_replans != 0:
        raise ValueError("Unique plans cannot replan")
    if (
        procedure.max_depth < 2
        or len(procedure.steps) > procedure.max_steps
        or 1 + len(procedure.steps) > procedure.max_expansions
    ):
        raise ValueError("Unique plan exceeds its declared execution limits")
    references = {}
    for step in procedure.steps:
        if step.on_failure != "fail":
            raise ValueError("Unique plan execution requires fail-on-failure steps")
        if not step.always_required or len(step.candidates) != 1:
            raise ValueError(
                "Unique plans require every step and exactly one candidate"
            )
        if any(
            isinstance(item.binding, ResourceValue) for item in step.inputs.values()
        ):
            raise ValueError("Unique plans do not automatically bind resources")
        ref = step.candidates[0]
        key = (ref.method_id, ref.version)
        if key in references and references[key] != ref:
            raise ValueError("One method version cannot have two digests")
        references[key] = ref
    pending = {step.id: step for step in procedure.steps}
    done: dict[str, MethodStep] = {}
    while pending:
        ready = sorted(
            key for key, step in pending.items() if set(step.depends_on) <= done.keys()
        )
        if not ready:
            raise ValueError("Unique plan has an unknown dependency or cycle")
        # Choose afresh after each step, so independent ready nodes always use
        # the same ordering regardless of how the author serialized the graph.
        key = ready[0]
        done[key] = pending.pop(key)
    return tuple(done.values())


def _json_object(values: Any) -> dict:
    def visit(value, depth=0):
        if depth > 32:
            raise ValueError("Plan values exceed their depth limit")
        if type(value) is dict:
            for key, child in value.items():
                if type(key) is not str:
                    raise ValueError("Plan object keys must be strings")
                visit(child, depth + 1)
        elif type(value) is list:
            for child in value:
                visit(child, depth + 1)
        elif type(value) is float:
            if not math.isfinite(value):
                raise ValueError("Plan values must be finite JSON")
        elif value is not None and type(value) not in (str, int, bool):
            raise ValueError("Plan values must be JSON")

    if type(values) is not dict:
        raise ValueError("Plan values must be an object")
    visit(values)
    if len(json.dumps(values, ensure_ascii=False, allow_nan=False).encode()) > 64000:
        raise ValueError("Plan values exceed 64000 bytes")
    return values


def _validate_slots(slots: dict[str, ValueSlot], values: Any) -> dict:
    values = _json_object(values)
    if not values.keys() <= slots.keys():
        raise ValueError("Plan values name an undeclared slot")
    for name, slot in slots.items():
        if name not in values:
            if slot.required or slot.on_missing != "omit":
                raise ValueError(f"Missing plan value: {name}")
        elif not slot.accepts(values[name]):
            raise ValueError(f"Plan value does not match its schema: {name}")
    return copy.deepcopy(values)


def validate_plan_inputs(definition: FormalMethodDefinition, values: Any) -> dict:
    """Validate all external inputs before opening a child invocation."""
    unique_plan(definition)
    slots = {
        name: ValueSlot.model_validate(item["slot"])
        for name, item in definition.interfaces()["inputs"].items()
    }
    return _validate_slots(slots, values)


def bind_step_inputs(
    step: MethodStep, caller_values: dict, accepted_outputs: dict[str, dict]
) -> dict:
    """Copy only declared bindings; absent predecessors never become omissions."""
    _json_object(caller_values)
    if not set(step.depends_on) <= accepted_outputs.keys():
        raise ValueError("A required predecessor has no accepted outputs")
    values = {}
    for name, item in step.inputs.items():
        binding = item.binding
        if isinstance(binding, CallerValue):
            if binding.name in caller_values:
                values[name] = caller_values[binding.name]
        elif isinstance(binding, LiteralValue):
            values[name] = binding.value
        elif isinstance(binding, StepValue):
            if binding.step not in step.depends_on:
                raise ValueError("Step binding is outside declared predecessors")
            outputs = _json_object(accepted_outputs[binding.step])
            if binding.output in outputs:
                values[name] = outputs[binding.output]
        else:
            raise ValueError("Unique plans do not automatically bind resources")
    return _validate_slots(
        {name: item.slot for name, item in step.inputs.items()}, values
    )


def validate_step_outputs(step: MethodStep, values: Any) -> dict:
    """Project an already validated child result into the step's output interface.

    A step may expose a subset of the child's declared outputs. The child
    adapter must validate its full output contract before calling this helper.
    """
    values = _json_object(values)
    return _validate_slots(
        step.outputs, {name: values[name] for name in step.outputs if name in values}
    )


def export_outputs(
    definition: FormalMethodDefinition, accepted_outputs: dict[str, dict]
) -> dict:
    """All mandatory steps must have accepted outputs, even unexported steps."""
    plan = unique_plan(definition)
    if set(accepted_outputs) != {step.id for step in plan}:
        raise ValueError("Plan outputs must cover exactly every required step")
    checked = {}
    for step in plan:
        checked[step.id] = _validate_slots(step.outputs, accepted_outputs[step.id])
    procedure = definition.procedure
    assert isinstance(procedure, Orchestration)
    values = {
        name: checked[ref.step][ref.output]
        for name, ref in procedure.exports.items()
        if ref.output in checked[ref.step]
    }
    slots = {
        name: ValueSlot.model_validate(item["slot"])
        for name, item in definition.interfaces()["outputs"].items()
    }
    return _validate_slots(slots, values)
